// ─── Normalize incoming payload from Flow #3 v2.3 ──────────────────────────────
// تنظيف وإثراء البيانات الواردة من Flow 3 بعد الويب هوك
// يتعامل مع البيانات لو كانت داخل body أو مباشرة

const raw = $input.first().json || {};
const d = raw.body || raw || {};  // ← التصحيح الرئيسي: يقرأ من body لو موجود

// 1. استخراج وتنظيف الحقول الأساسية
const phone = (d.phone || d.normalized_phone || '').trim().replace(/^0/, '+966');
let phones_found = Array.isArray(d.phones_found) ? d.phones_found : [];
if (phone && !phones_found.includes(phone)) {
  phones_found.push(phone);
}
phones_found = [...new Set(phones_found.filter(p => p && p.startsWith('+966')))];

// 2. اسم ومصدر نظيف
const name = d.name || d.username || d.normalized_name || 'غير معروف';
const source = (d.source || 'unknown').replace(/FacebookFacebook/gi, 'Facebook').trim();

// 3. تصنيف lead_type (محسن ليشمل luxury و couple)
const cat = (d.category || d.lead_category || 'unknown').toLowerCase();
let lead_type = 'B2C_hot';
if (cat.includes('b2b')) lead_type = 'B2B_high';
else if (cat.includes('group') || cat.includes('large')) lead_type = 'B2C_group';
else if (cat.includes('family')) lead_type = 'B2C_family';
else if (cat.includes('luxury') || d.budget_signal === 'luxury') lead_type = 'B2C_luxury';
else if (cat.includes('couple') || cat.includes('زوج')) lead_type = 'B2C_couple';

// 4. حساب pax (مع استخراج تقديري من الرسالة)
let pax = d.pax_hint || d.pax || 0;
if (pax === 0) {
  const msgLower = (d.message || '').toLowerCase();
  if (msgLower.includes('عائلة') || msgLower.includes('زوجتي') || msgLower.includes('اولاد') || msgLower.includes('اطفال')) pax = 4;
  else if (msgLower.includes('مجموعة') || msgLower.includes('اصدقاء')) pax = 6;
  else if (msgLower.includes('زوج') || msgLower.includes('زوجين')) pax = 2;
}

// 5. score و urgency (مع fallback)
const score = d.final_score || d.score || 0;
const urgency = (d.radar_urgency || d.urgency || 'unknown').toLowerCase();

// 6. SLA (وقت الاستجابة بالدقائق – محسن)
let sla_minutes = 60;
if (urgency.includes('immediate') || score >= 90 || lead_type === 'B2B_high') sla_minutes = 15;
else if (urgency.includes('soon') || score >= 75) sla_minutes = 30;
else if (lead_type.includes('luxury') || lead_type.includes('family')) sla_minutes = 45;

// 7. المخرج النهائي (منظم وكامل لـ Flow 6)
return [{ json: {
  phone,
  name,
  lead_id: d.lead_id || d.id || '',
  final_score: score,
  status: d.status || (score >= 80 ? 'Hot' : (score >= 55 ? 'Warm' : 'Cold')),
  lead_category: cat,
  lead_type,
  preferred_channel: d.preferred_channel || 'telegram',
  recommended_action: d.recommended_action || 'followup',
  radar_urgency: urgency,
  message: (d.message || '').substring(0, 500) + ((d.message || '').length > 500 ? '...' : ''),
  phones_found,
  source,
  scored_at: d.scored_at || new Date().toISOString(),
    pax,
  sla_minutes,
  handoff_at: new Date().toISOString(),

  // ⭐ أضف هنا:
  stars_preference: d.stars_preference || 'unknown',
  budget_signal: d.budget_signal || 'unknown',
  travel_group: d.travel_group || 'unknown'
} }];

// ─── Merge incoming payload with stored profile v2.4 – نهائي وخالي من الأخطاء ──────────
// دمج البيانات الواردة من Normalize مع البروفايل المخزن من GSheets

const incoming = $('Code – Normalize Handoff Payload').first().json || {};
const profileItems = $input.all();
const profile = profileItems.length > 0 && profileItems[0].json ? profileItems[0].json : {};

// تحقق إذا كان اللييد محجوز أو مغلق سابقاً
const isBooked = ['booked', 'closed', 'converted', 'done', 'rejected'].includes(
  (profile.status || '').toLowerCase()
);

// دمج البيانات مع الأولوية للبيانات الجديدة (incoming)
return [{
  json: {
    ...profile,                    // البروفايل القديم كأساس (تاريخ، journey_step، إلخ)
    ...incoming,                   // الأولوية للبيانات الجديدة من Flow 3

    // تصحيح الحقول الحساسة لو undefined أو فارغة (بدون استخدام d)
    final_score: incoming.final_score || profile.final_score || 0,
    status: incoming.status || profile.status || 'new',
    lead_category: incoming.lead_category || profile.lead_category || 'unknown',
    lead_type: incoming.lead_type || profile.lead_type || 'B2C_hot',
    stars_preference: incoming.stars_preference || profile.stars_preference || 'unknown',
    budget_signal: incoming.budget_signal || profile.budget_signal || 'unknown',
    travel_group: incoming.travel_group || profile.travel_group || 'unknown',
    pax_hint: incoming.pax || incoming.pax_hint || profile.pax_hint || 0,
    radar_urgency: incoming.radar_urgency || profile.radar_urgency || 'unknown',
    recommended_action: incoming.recommended_action || profile.recommended_action || 'followup',
    preferred_channel: incoming.preferred_channel || profile.preferred_channel || 'telegram',

    // حقول إضافية مهمة لـ Flow 6
    stored_status: profile.status || 'new',
    is_booked: isBooked,
    last_seen_at: profile.last_seen_at || new Date().toISOString(),
    interaction_count: profile.interaction_count || 0,

    // تصحيح scored_at و handoff_at بشكل آمن جدًا
    scored_at: incoming.scored_at || profile.scored_at 
      ? new Date(incoming.scored_at || profile.scored_at).toISOString()
      : new Date().toISOString(),
    handoff_at: incoming.handoff_at 
      ? new Date(incoming.handoff_at).toISOString()
      : new Date().toISOString(),

    // personalization جاهزة للاستخدام في تليجرام أو Flow 5
    personalization: {
      name: incoming.name || profile.name || 'العميل',
      group_size: incoming.pax || incoming.pax_hint || profile.pax_hint || 1,
      budget: incoming.budget_signal || profile.budget_signal || 'غير معروف',
      stars: incoming.stars_preference || profile.stars_preference || 'غير معروف'
    }
  }
}];

// ── B2C HOT – حجز فردي عاجل ──────────────────────────────────────────────────
const d = $input.first().json;
const budgetLine = d.budget_signal === 'luxury' ? 'اهتمامه بـ 5 نجوم' : d.budget_signal === 'budget' ? 'يبحث عن أسعار اقتصادية' : 'ميزانية متوسطة';
const starsLine = d.stars_preference !== 'unknown' ? ` | تفضيل: ${d.stars_preference}` : '';

return [{ json: {
  ...d,
  task_title: `🔥 حجز فوري B2C – ${d.name}`,
  task_type: 'b2c_hot_booking',
  priority: 'urgent',
  action_required: 'اتصل فوراً، عميل حجز جاهز',
  task_notes: `${budgetLine}${starsLine} | درجة: ${d.score}/100 | عاجلية: ${d.urgency}`,
  woo_product_id: 101
} }];

// ════════════════════════════════════════════════════════════════════════
// Flow #6 › Code – Prepare B2C Family Task | نظام رادار Bluevia Travel v4.0 — مُصحح
// ════════════════════════════════════════════════════════════════════════

const d = $input.first()?.json || {};

// ── توليد task_id فريد ─────────────────────────────────────────────────
const ts = Date.now().toString().slice(-6);
const rnd = Math.floor(Math.random() * 1000).toString().padStart(3, '0');
const task_id = `TSK-${ts}${rnd}`;

// ── تحديد نوع المهمة ──────────────────────────────────────────────────
const task_type = 'b2c_family_booking';

// ── تحديد الأولوية بناءً على الدرجة ───────────────────────────────────
let priority = 'normal';
if (d.final_score >= 90) priority = 'urgent';
else if (d.final_score >= 70) priority = 'high';

// ── تحديد المندوب (فارغ افتراضياً لفريق المبيعات) ─────────────────────
const assigned_to = 'sales_team';

// ── حالة المهمة (ليست تصنيف العميل!) ──────────────────────────────────
const status = 'open';  // ✅ open / closed / converted / escalated

// ── توحيد صيغة الهاتف ─────────────────────────────────────────────────
const phone = d.phone?.startsWith('+') ? d.phone : `+${d.phone}`;

// ── ملء lead_name ─────────────────────────────────────────────────────
const lead_name = d.name || d.full_name || 'غير معروف';

// ── ملاحظات مفصلة لفريق المبيعات ─────────────────────────────────────
const notes = `عميل يطلب خدمة Bluevia Travel ${d.stars_preference || '5 نجوم'} قريب الحرم ليوم ${d.check_in_hint || 'غير محدد'} لعائلة من ${d.pax || 4} أشخاص. ميزانية ${d.budget_signal || 'unknown'}. رقم الهاتف: ${phone}. مصدر: ${d.source}. الرسالة: ${d.message || d.last_message || ''}`.substring(0, 500);

// ── عنوان المهمة ──────────────────────────────────────────────────────
const task_title = `👨‍👩‍👧 حجز عائلي – ${lead_name}`;

// ── الإجراء المطلوب ───────────────────────────────────────────────────
const action_required = 'تواصل وأرسل عروض الغرف العائلية';

// ─ـ ملاحظات المهمة المختصرة ───────────────────────────────────────────
const task_notes = `عائلة | نجوم: ${d.stars_preference} | ميزانية: ${d.budget_signal} | درجة: ${d.final_score || d.score}/100`;

// ── personalization للرسائل ──────────────────────────────────────────
const personalization = {
  name: lead_name,
  group_size: d.pax || 4,
  budget: d.budget_signal || 'unknown',
  stars: d.stars_preference || 'unknown'
};

// ── الإخراج النهائي — جميع الحقول المطلوبة ───────────────────────────
return [{
  json: {
    ...d,
    // حقول المهمة الأساسية
    task_id: task_id,
    task_type: task_type,
    priority: priority,
    assigned_to: assigned_to,
    status: status,  // ✅ حالة المهمة: open
    sla_minutes: d.sla_minutes || 30,
    created_at: new Date().toISOString(),

    // حقول الهوية الموحدة
    lead_name: lead_name,
    lead_score: d.final_score || d.score || 100,
    phone: phone,

    // حقول العرض
    task_title: task_title,
    action_required: action_required,
    task_notes: task_notes,
    personalization: personalization,

    // حالة التخزين
    stored_status: 'new',

    // طوابع زمنية إضافية
    handoff_at: new Date().toISOString(),
    scored_at: d.scored_at || new Date().toISOString()
  }
}];

// ── B2C GROUP – مجموعة ────────────────────────────────────────────────────────
const d = $input.first().json;
const paxStr = d.pax > 0 ? `${d.pax} شخص` : 'مجموعة كبيرة';
return [{ json: {
  ...d,
  task_title: `👥 حجز مجموعة (${paxStr}) – ${d.name}`,
  task_type: 'b2c_group_booking',
  priority: 'high',
  action_required: 'أرسل عرض سعر جماعي + تأكيد توفر الغرف',
  task_notes: `${paxStr} | يحتاج تسعير خاص | درجة: ${d.score}/100`,
  woo_product_id: 103
} }];

// ── B2B – شراكة تجارية ────────────────────────────────────────────────────────
const d = $input.first().json;
const catLine = d.category === 'B2B_government' ? 'جهة حكومية' : d.category === 'B2B_conference' ? 'تنظيم مؤتمرات' : 'وكالة سياحة/شركة';
return [{ json: {
  ...d,
  task_title: `🏢 شراكة B2B – ${d.name} (${catLine})`,
  task_type: 'b2b_partnership',
  priority: 'high',
  action_required: 'حدد موعد اجتماع، أرسل Profile الشركة + خطة أسعار الجملة',
  task_notes: `${catLine} | درجة: ${d.score}/100 | تفاعلات سابقة: ${d.interaction_count}`,
  woo_product_id: 104
} }];

// ── FALLBACK – نوع غير معروف ──────────────────────────────────────────────────
const d = $input.first().json;
return [{ json: {
  ...d,
  task_title: `📋 Lead جديد – ${d.name}`,
  task_type: 'general_followup',
  priority: 'normal',
  action_required: 'تواصل وحدد احتياج العميل',
  task_notes: `درجة: ${d.score}/100 | المصدر: ${d.source}`,
  woo_product_id: 101
} }];

