// ─── Check If Still Open v2.3 – آمن 100% ويضمن boolean ────────────────────────

const taskData = $('Merge All Task Preparations').first().json || {};  // fallback آمن

// فلتر آمن جدًا: نتأكد إن كل item ليه json قبل الوصول للحقول
const openTasks = $input.all().filter(i => {
  if (!i || !i.json) return false;
  return i.json.status === 'open' || i.json.phone || i.json.task_id;
});

const stillOpen = openTasks.length > 0;  // ده boolean دائمًا (true/false)

return [{ json: { 
  ...taskData,
  still_open_2h: stillOpen,           // boolean صريح
  open_tasks_count: openTasks.length, // للشفافية
  debug_open_tasks: openTasks.length   // لو عايز تشوف العدد في اللوج
} }];

