// ════════════════════════════════════════════════════════════════════════
// Flow #6 › Code – Check Still Open After 2h | نظام رادار Bluevia Travel v4.0 — تشخيصي
// ════════════════════════════════════════════════════════════════════════

const d = $input.first()?.json || {};

// ── حساب الوقت المنقضي بدقة ───────────────────────────────────────────
const createdAt = new Date(d.created_at || d.handoff_at || Date.now());
const now = new Date();
const diffMs = now - createdAt;
const hoursElapsed = diffMs / (1000 * 60 * 60); // تحويل لـ ساعات

// ── التحقق من حالة المهمة ─────────────────────────────────────────────
const taskStatus = (d.status || d.task_status || 'open').toLowerCase().trim();
const isOpen = taskStatus === 'open';
const isEscalated = taskStatus === 'escalated';
const isClosed = ['closed', 'converted', 'cancelled'].includes(taskStatus);

// ── الحساب النهائي لـ still_open_2h ───────────────────────────────────
const still_open = isOpen && !isEscalated && !isClosed;
const still_open_2h = still_open && hoursElapsed >= 2;

// ── تسجيلات تشخيصية (للتتبع في اللوج) ─────────────────────────────────
const debug_info = {
  created_at: d.created_at,
  now: now.toISOString(),
  hours_elapsed: Math.round(hoursElapsed * 100) / 100,
  task_status: taskStatus,
  is_open: isOpen,
  is_escalated: isEscalated,
  is_closed: isClosed,
  still_open: still_open,
  still_open_2h: still_open_2h
};

// ── الإخراج النهائي ──────────────────────────────────────────────────
return [{
  json: {
    ...d,
    // ✅ الحقول المطلوبة للعقدة الشرطية (boolean صريح)
    still_open_2h: Boolean(still_open_2h),
    still_open: Boolean(still_open),

    // حقول التشخيص (تظهر في اللوج للمراجعة)
    _debug_hours_elapsed: Math.round(hoursElapsed * 100) / 100,
    _debug_task_status: taskStatus,
    _debug_still_open_calc: debug_info,

    // حقول التصعيد
    needs_escalation: Boolean(still_open_2h),
    escalation_priority: d.sla_minutes <= 15 ? 'urgent' : 
                         d.sla_minutes <= 30 ? 'high' : 'normal',
    checked_at: now.toISOString(),

    // ضمان وجود task_id
    task_id: d.task_id || `TSK-${Date.now().toString().slice(-6)}-${Math.floor(Math.random() * 1000)}`
  }
}];

